SELECT COALESCE(SUM([_veridelta_rows]), 0) AS [_veridelta_total] FROM (SELECT COUNT_BIG(*) AS [_veridelta_rows] FROM (SELECT LOWER(TRIM(N'⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩' FROM CAST([src].[code] AS NVARCHAR(MAX)) COLLATE Latin1_General_100_BIN2)) AS [code] FROM [shop].[orders_v1] AS [src]) AS [_veridelta_keys] GROUP BY ([code] + N'|') COLLATE Latin1_General_100_BIN2 HAVING COUNT_BIG(*) > 1) AS [_veridelta_duplicates]

